#!/bin/bash
sed -i 's/Entrar com Google\n          <\/button>/Entrar com Google\n          <\/button>\n          {loginError \&\& (\n            <div className="mt-6 p-4 bg-red-50 border border-red-200 text-red-700 text-sm rounded-xl text-left">\n              <p className="font-bold mb-1">Erro de Autenticação<\/p>\n              <p className="mb-2">{loginError}<\/p>\n              <p className="text-xs opacity-90">\n                Dica: Se o erro for "unauthorized-domain", você precisa adicionar o domínio deste aplicativo (ex: *.run.app) na lista de "Domínios Autorizados" no console do Firebase (Authentication > Settings).\n              <\/p>\n              <p className="text-xs opacity-90 mt-1">\n                Dica 2: Se a janela de login fechar imediatamente ou não abrir, experimente abrir este aplicativo em uma <strong>nova aba do navegador<\/strong> em vez de usar o painel de visualização.\n              <\/p>\n            <\/div>\n          )}/g' src/App.tsx
